mapper.insert:
insert into t_glue_span_receive (id,send_id,schedule_date,entrust_mix_area,entrusted_mix_area,glue,send_qty,receive_qty,machine_code,recipe_type,recipe_version_id,recipe_stage,expect_demand_time,receive_status,receive_time,receive_person,source,is_auto, schedule_id,create_by,create_time,update_by,update_time,del_flag,remark) select NULL id, x.* from (
select #{glueSpanReceive.sendId,jdbcType=DOUBLE} send_id, #{glueSpanReceive.scheduleDate,jdbcType=DATE} schedule_date, #{glueSpanReceive.entrustMixArea,jdbcType=VARCHAR} entrust_mix_area, #{glueSpanReceive.entrustedMixArea,jdbcType=VARCHAR} entrusted_mix_area, #{glueSpanReceive.glue,jdbcType=VARCHAR} glue, #{glueSpanReceive.sendQty,jdbcType=DOUBLE} send_qty, #{glueSpanReceive.receiveQty,jdbcType=DOUBLE} receive_qty, #{glueSpanReceive.machineCode,jdbcType=VARCHAR} machine_code, #{glueSpanReceive.recipeType,jdbcType=VARCHAR} recipe_type, #{glueSpanReceive.recipeVersionId,jdbcType=VARCHAR} recipe_version_id, #{glueSpanReceive.recipeStage,jdbcType=VARCHAR} recipe_stage, #{glueSpanReceive.expectDemandTime,jdbcType=DATE} expect_demand_time, #{glueSpanReceive.receiveStatus,jdbcType=VARCHAR} receive_status, #{glueSpanReceive.receiveTime,jdbcType=DATE} receive_time, #{glueSpanReceive.receivePerson,jdbcType=VARCHAR} receive_person, #{glueSpanReceive.source,jdbcType=VARCHAR} source,#{glueSpanReceive.isAuto,jdbcType=VARCHAR} is_auto, #{glueSpanReceive.scheduleId,jdbcType=DOUBLE} schedule_id, #{glueSpanReceive.createBy,jdbcType=VARCHAR} create_by, #{glueSpanReceive.createTime,jdbcType=DATE} create_time, #{glueSpanReceive.updateBy,jdbcType=VARCHAR} update_by, #{glueSpanReceive.updateTime,jdbcType=DATE} update_time, #{glueSpanReceive.delFlag,jdbcType=VARCHAR} del_flag, #{glueSpanReceive.remark,jdbcType=VARCHAR} remark from dual
) x

mapper.select:
select gsr.id, gsr.send_id, gsr.schedule_date, gsr.entrust_mix_area, gsr.entrusted_mix_area, gsr.glue, gsr.send_qty, gsr.receive_qty, gsr.machine_code, gsr.recipe_type, gsr.recipe_version_id, gsr.recipe_stage, gsr.expect_demand_time, gsr.receive_status, gsr.receive_time, gsr.receive_person, gsr.source, gsr.create_by, gsr.create_time, gsr.update_by, gsr.update_time, gsr.del_flag, gsr.remark, gsr.is_auto, gsr.schedule_id, gss.SEND_PERSON, trt.RECIPE_TYPE_NAME, tmi.MACHINE_NAME, ifnull(gf.MID_FINISH_QTY, 0) + ifnull(gf.NIGHT_FINISH_QTY, 0) + ifnull(gf.DAY_FINISH_QTY, 0) AS finishQty from t_glue_span_receive gsr LEFT JOIN T_GLUE_SPAN_SEND gss ON gsr.SEND_ID = gss.ID AND gss.DEL_FLAG = '0' left join t_recipe_type trt on gsr.recipe_type = trt.recipe_type_code and trt.del_flag = 0 left join (select mix_area, machine_code, machine_name from t_mix_machine where del_flag = 0 union select mix_area, machine_code, machine_name from t_lhfl_machine where del_flag = 0) tmi on gsr.machine_code = tmi.machine_code and gsr.entrusted_mix_area = tmi.mix_area LEFT JOIN (SELECT SUM(MID_FINISH_QTY) MID_FINISH_QTY,SUM(NIGHT_FINISH_QTY) NIGHT_FINISH_QTY,SUM(DAY_FINISH_QTY) DAY_FINISH_QTY, SCHEDULE_DATE, MIX_AREA, GLUE FROM T_GLUE_FINISH WHERE DEL_FLAG = '0' GROUP BY SCHEDULE_DATE, MIX_AREA, GLUE) gf ON gsr.SCHEDULE_DATE = gf.SCHEDULE_DATE AND gsr.ENTRUSTED_MIX_AREA = gf.MIX_AREA AND gsr.GLUE = gf.GLUE where gsr.DEL_FLAG = '0' and gsr.schedule_date = #{scheduleDate} and gsr.entrusted_mix_area = #{entrustedMixArea} and gsr.entrust_mix_area = #{entrustMixArea}
and gsr.entrusted_mix_area in
#{item}
and INSTR(gsr.glue, #{glue}) > 0 and gsr.receive_status = #{receiveStatus} and gsr.source = #{source} order by receive_status asc, gsr.create_time desc order by ${orderStr}

WITH temp_table AS (
SELECT #{index} id, #{data.scheduleDate,jdbcType=DATE} schedule_date,#{data.entrustMixArea,jdbcType=VARCHAR} entrust_mix_area, #{data.entrustedMixArea,jdbcType=VARCHAR} entrusted_mix_area, #{data.glue,jdbcType=VARCHAR} glue FROM dual
) select t.id errorRow from t_glue_span_receive m inner join temp_table t on m.schedule_date = t.schedule_date and m.entrust_mix_area = t.entrust_mix_area and m.entrusted_mix_area = t.entrusted_mix_area and m.glue = t.glue and m.del_flag = '0'

select count(1)
from t_glue_span_receive
where DEL_FLAG = '0' and receive_status = '0'
and schedule_date = #{scheduleDate,jdbcType=DATE}
and entrusted_mix_area = #{entrustedMixArea,jdbcType=VARCHAR}
and source = #{source}

